// Auto-generated Base64 Image Assets for offline, reliable jsPDF embedding
export const base64Images = {
  "accidental_risk": "data:image/jpeg;base64,",
  "education_female": "data:image/jpeg;base64,",
  "education_male": "data:image/jpeg;base64,",
  "eswara_moorthy": "data:image/jpeg;base64,",
  "hero": "data:image/jpeg;base64,",
  "life_risk": "data:image/jpeg;base64,",
  "marriage": "data:image/jpeg;base64,",
  "retirement": "data:image/jpeg;base64,",
};

export const getFeatureImage = (featureId, gender) => {
  if (featureId === "education") {
    return gender === "Female" ? base64Images.education_female : base64Images.education_male;
  }
  const keyMap = {
    marriage: base64Images.marriage,
    retirement: base64Images.retirement,
    accidentalRisk: base64Images.accidental_risk,
    lifeRisk: base64Images.life_risk,
    hero: base64Images.hero
  };
  return keyMap[featureId] || base64Images.hero;
};
